                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_eu'), 'warning');
                    return false;
                }
                decisions.priceIncrease = pi;
                decisions.localCostCut = lc;
                decisions.mechanize = mz;
                decisions.euDiversification = eu;
            } else if (period === 2) {
                const strat = document.getElementById('r2StrategyInput').value;
                const hr = parseFloat(document.getElementById('r2HedgeInput').value);
                if (isNaN(hr) || hr < 0 || hr > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_hedge'), 'warning');
                    return false;
                }
                decisions.r2Strategy = strat;
                decisions.r2HedgeRatio = hr;
            } else if (period === 3) {
                const fwd = parseFloat(document.getElementById('forwardHedgeInput').value) || 0;
                const opt = parseFloat(document.getElementById('optionHedgeInput').value) || 0;
                const nat = parseFloat(document.getElementById('naturalHedgeInput').value) || 0;
                const inv = parseFloat(document.getElementById('invoicingInput').value) || 0;
                const div = parseFloat(document.getElementById('diversificationInput').value) || 0;
                const res = parseFloat(document.getElementById('cashReserveInput').value) || 0;
                if (fwd + opt > 100) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_alloc'), 'warning');
                    return false;
                }
                decisions.forwardHedge = fwd;
                decisions.optionHedge = opt;
                decisions.naturalHedge = nat;
                decisions.invoicing = inv;
                decisions.diversification = div;
                decisions.cashReserve = res;
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const period = state.currentPeriod;
            const round = this.ROUNDS[period - 1];
            const fx = round.fxRate;
            const contractUsd = ds.contractUsd;
            const pesoCostBase = ds.pesoCostBase;
            const usdCostUsd = ds.usdCostUsd;

            let revenue = 0;
            let costs = 0;
            let profit = 0;
            let note = '';

            if (period === 1) {
                const priceMult = 1 + d.priceIncrease / 100;
                let volMult = 1 - 1.5 * (d.priceIncrease / 100);
                if (volMult < 0) volMult = 0;
                const effectiveUsd = contractUsd * priceMult * volMult;
                const eurFx = 4.50;
                const euShare = d.euDiversification / 100;
                const usdShare = 1 - euShare;
                const entryCost = euShare > 0 ? 80000 * (d.euDiversification / 30) : 0;
                revenue = effectiveUsd * usdShare * fx + effectiveUsd * euShare * eurFx;
                const pesoCosts = pesoCostBase * (1 - d.localCostCut / 100);
                const importedCosts = usdCostUsd * fx;
                const reputationalCost = pesoCostBase * (d.localCostCut / 100) * 0.4;
                const mechSavings = d.mechanize ? 60000 : 0;
                const mechCapex = d.mechanize ? 900000 : 0;
                costs = pesoCosts + importedCosts + entryCost + mechCapex + reputationalCost - mechSavings;
                profit = revenue - costs;
                note = 'Strong peso: USD revenue translates to fewer pesos; cheaper imports help only partly.';
            } else if (period === 2) {
                const jCurveFactor = 0.92;
                const baseRevenue = contractUsd * fx * jCurveFactor;
                const pesoCosts = pesoCostBase;
                const importedCosts = usdCostUsd * fx;
                let strategyCost = 0;
                let strategyAdj = 0;
                if (d.r2Strategy === 'pocket') {
                    strategyCost = 0;
                } else if (d.r2Strategy === 'reinvest') {
                    strategyCost = 600000;
                    strategyAdj = 0;
                } else if (d.r2Strategy === 'hedge') {
                    const hedgedNotional = (d.r2HedgeRatio / 100) * contractUsd * fx;
                    strategyCost = hedgedNotional * 0.015;
                } else if (d.r2Strategy === 'diversify') {
                    strategyCost = 200000;
                    strategyAdj = 80000;
                } else if (d.r2Strategy === 'prepay') {
                    strategyAdj = usdCostUsd * 0.5;
                }
                revenue = baseRevenue;
                costs = pesoCosts + importedCosts + strategyCost - strategyAdj;
                profit = revenue - costs;
                note = 'Weak peso lifts revenue, but imported inputs cost 50% more in CO$, and the J-curve eats Q1 volume.';
            } else if (period === 3) {
                const directHedge = Math.min(100, d.forwardHedge + d.optionHedge) / 100;
                const indirectReduction = Math.min(0.4, (d.naturalHedge * 0.4 + d.invoicing * 0.3 + d.diversification * 0.5) / 100);
                const totalProtection = directHedge + (1 - directHedge) * indirectReduction;
                const unhedged = 1 - totalProtection;
                const reserveProt = Math.min(0.5, d.cashReserve / 200);
                const effectiveExposure = unhedged * (1 - reserveProt);
                const riskPenalty = effectiveExposure * effectiveExposure * 2400000;
                const fwdCost = (d.forwardHedge / 100) * contractUsd * fx * 0.025;
                const optCost = (d.optionHedge / 100) * contractUsd * fx * 0.04;
                const overHedgeAmt = Math.max(0, (d.forwardHedge + d.optionHedge) - 75);
                const overHedgeCost = overHedgeAmt * overHedgeAmt * 1200;
                const naturalCost = (d.naturalHedge / 100) * 40000;
                const invoicingCost = (d.invoicing / 100) * 30000;
                const diversifyCost = (d.diversification / 100) * 80000;
                const reserveOppCost = (d.cashReserve / 100) * 60000;
                revenue = contractUsd * fx;
                costs = pesoCostBase + usdCostUsd * fx + fwdCost + optCost + overHedgeCost + naturalCost + invoicingCost + diversifyCost + reserveOppCost + riskPenalty;
                profit = revenue - costs;
                note = 'Volatility risk allocated across the toolkit. Risk is shifted, not removed.';
            }

            ds.cash += profit;
            ds.cumulativeProfit += profit;
            ds.profitHistory.push(Math.round(profit));
            ds.fxRateHistory.push(fx);
            ds.revenueHistory.push(Math.round(revenue));
            // platform score: running total of the rounded round profits, mapped to 0 to 100 through the same bands as getPerformanceSummary
            const runProfit = ds.profitHistory.reduce(function(s, p) { return s + p; }, 0);
            let runScore;
            if (runProfit > 1500000) runScore = 80 + Math.min(20, ((runProfit - 1500000) / 1500000) * 20);
            else if (runProfit > 800000) runScore = 60 + ((runProfit - 800000) / 700000) * 19;
            else if (runProfit > 0) runScore = 40 + (runProfit / 800000) * 19;
            else runScore = Math.max(0, 39 + (runProfit / 40000));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(runScore))) });

            const self = this;
            const nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod, domainState: state.domainState });
            }, 500);

            return {
                period: state.currentPeriod,
                fxRate: fx,
                revenue: Math.round(revenue),
                costs: Math.round(costs),
                profit: Math.round(profit),
                cumulativeProfit: Math.round(ds.cumulativeProfit),
                cash: Math.round(ds.cash),
                note: note
            };
        }

        _t(key) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                const v = window.mySimulation.t(key);
                if (v) return v;
            }
            return key;
        }

        _isRunComplete(period) {
            const st = (window.mySimulation && window.mySimulation.state) || {};
            const maxP = parseInt(st.maxPeriods, 10) || this.ROUNDS.length;
            const hist = Array.isArray(st.history) ? st.history : [];
            if (hist.length >= maxP) return true;
            return (period || 1) > maxP;
        }

        _syncControlsFromDecisions(state) {
            const dec = (state && state.decisions) || {};
            const numeric = {
                priceIncreaseInput: 'priceIncrease', localCostCutInput: 'localCostCut',
                euDivInput: 'euDiversification', r2HedgeInput: 'r2HedgeRatio',
                forwardHedgeInput: 'forwardHedge', optionHedgeInput: 'optionHedge',
                naturalHedgeInput: 'naturalHedge', invoicingInput: 'invoicing',
                diversificationInput: 'diversification', cashReserveInput: 'cashReserve'
            };
            Object.keys(numeric).forEach(function(id) {
                const el = document.getElementById(id);
                const v = dec[numeric[id]];
                if (el && v !== undefined && v !== null) el.value = String(v);
            });
            const mz = document.getElementById('mechanizeInput');
            if (mz && dec.mechanize !== undefined) mz.checked = !!dec.mechanize;
            const st = document.getElementById('r2StrategyInput');
            if (st && dec.r2Strategy) st.value = dec.r2Strategy;
        }

        _updateBriefing(state) {
            const period = state.currentPeriod || 1;
            const over = this._isRunComplete(period);
            const actions = document.querySelector('.curgame-action-row');
            if (actions) actions.style.display = over ? 'none' : 'flex';
            const done = document.getElementById('completionPanel');
            if (done) {
                done.style.display = over ? 'block' : 'none';
                if (over && !done.innerHTML) {
                    done.innerHTML = (window.mySimulation && window.mySimulation.lastCompletionHTML) ||
                        ('<div class="curgame-debrief"><h3>' + this._t('debrief_heading') + '</h3></div>');
                }
            }
            if (over) {
                ['round1Panel', 'round2Panel', 'round3Panel'].forEach(function(id) {
                    const p = document.getElementById(id);
                    if (p) p.style.display = 'none';
                });
                return;
            }
            const idx = Math.min(period - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const headlineEl = document.getElementById('roundHeadline');
            if (headlineEl) headlineEl.textContent = this._t('r' + (idx + 1) + '_headline');
            const descEl = document.getElementById('roundDescription');
            if (descEl) descEl.textContent = this._t('r' + (idx + 1) + '_description');
            const fxOldEl = document.getElementById('fxOldDisplay');
            if (fxOldEl) fxOldEl.textContent = 'CO$ ' + round.fxOld.toFixed(2);
            const fxEl = document.getElementById('fxRateDisplay');
            if (fxEl) fxEl.textContent = 'CO$ ' + round.fxRate.toFixed(2);
            const p1 = document.getElementById('round1Panel');
            const p2 = document.getElementById('round2Panel');
            const p3 = document.getElementById('round3Panel');
            if (p1) p1.style.display = (period === 1) ? 'block' : 'none';
            if (p2) p2.style.display = (period === 2) ? 'block' : 'none';
            if (p3) p3.style.display = (period === 3) ? 'block' : 'none';
        }

