        getHint(state, results) {
            if (!results) return null;
            if (state.currentPeriod === 1 && state.decisions.priceIncrease >= 8) {
                return window.mySimulation.t('hint_price_high');
            }
            if (state.currentPeriod === 2 && state.decisions.r2Strategy === 'pocket') {
                return window.mySimulation.t('hint_pocket');
            }
            if (state.currentPeriod === 3) {
                const total = (state.decisions.forwardHedge || 0) + (state.decisions.optionHedge || 0);
                if (total >= 90) return window.mySimulation.t('hint_overhedge');
                if (total <= 20) return window.mySimulation.t('hint_underhedge');
            }
            if (results.profit < 0) return window.mySimulation.t('hint_loss');
            return null;
        }

