                { key: 'results.costs', label: 'Costs', i18nKey: 'col_costs', formatter: (v) => 'CO$ ' + v.toLocaleString() },
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: (v) => 'CO$ ' + v.toLocaleString() }
            ];
