        getPerformanceSummary(history) {
            if (!history.length) return {};
            const profits = history.map(r => (r.results && r.results.profit) || 0);
            const totalProfit = profits.reduce((s, p) => s + p, 0);
            let perf = 'beginner';
            if (totalProfit > 800000) perf = 'good';
            if (totalProfit > 1500000) perf = 'excellent';
            const perfKey = 'perf_' + perf;

            // 0-100 composite anchored on this sim own band thresholds, so the number
            // and the label can never disagree. Band boundaries are unchanged.
            let overall;
            if (totalProfit > 1500000) {
                overall = 80 + Math.min(20, ((totalProfit - 1500000) / 1500000) * 20);
            } else if (totalProfit > 800000) {
                overall = 60 + ((totalProfit - 800000) / 700000) * 19;
            } else if (totalProfit > 0) {
                overall = 40 + (totalProfit / 800000) * 19;
            } else {
                overall = Math.max(0, 39 + (totalProfit / 40000));
            }
            overall = Math.max(0, Math.min(100, Math.round(overall)));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                totalProfit: totalProfit,
                performance: perf,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights: [
                    this._t('insight_strong'),
                    this._t('insight_weak'),
                    this._t('insight_hedge')
                ]
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = this._t.bind(this);
            const esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            const money = 'CO$ ' + Math.round(s.totalProfit || 0).toLocaleString();
            const rows = [[t('debrief_profit'), money]].map(function(r) {
                return '<li><span class="curgame-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="curgame-debrief-v">' + esc(r[1]) + '</span></li>';
            }).join('');
            const ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="curgame-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="curgame-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="curgame-debrief-list">' + rows + '</ul>' +
                     '<div class="curgame-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

